"""Chapter 6 content: methodology and software implementation (CropSight). All numbers come from docs/REPORT_FACTS.md and experiments/*/metrics.json."""
from __future__ import annotations

from doc_common import CHARTS, DIAG, ROOT, metrics

Q = metrics("quality")
P = metrics("price")
R = metrics("real_images")
DL = metrics("delivery")
IO = metrics("iot")


def src(path: str, start: int, end: int) -> str:
    """Real source lines (1-based, inclusive) from the project, so listings never drift from the code."""
    lines = (ROOT / path).read_text(encoding="utf-8").splitlines()
    return "\n".join(lines[start - 1:end])


def grab(path: str, marker: str, n: int) -> str:
    """`n` real source lines starting at the first line that contains `marker`."""
    lines = (ROOT / path).read_text(encoding="utf-8").splitlines()
    i = next(k for k, line in enumerate(lines) if marker in line)
    return "\n".join(lines[i:i + n])


def pct(x, nd=1):
    return f"{x * 100:.{nd}f} %"


# ---------------------------------------------------------------------------------------------------------------- 6.1
def sec_method_overview(d):
    d.h2("Overall Methodology")
    d.paras(
        "CropSight follows a post-harvest decision chain: a farmer photographs a harvested crop, the system turns the photograph into numbers, "
        "grades it, estimates the price it should fetch and the best day to sell, ranks the buyers who would pay most for the least spoilage, "
        "publishes the lot to a marketplace, and then tracks the shipment until delivery. The base paper [1] combines IoT sensing, deep learning and "
        "explainable AI for **pre-harvest** advice (soil analysis, irrigation, crop and fertiliser recommendation). CropSight keeps that three-part idea "
        "(sensing, learning, explanation) and moves it after the harvest: image features replace soil readings, a price model replaces the irrigation "
        "advisor, SHAP [13], [14] provides the explanations, and a sensor stream monitors storage and transport.",
        "Two differences from the base paper must be stated at the outset. First, the learning components are **classical machine learning**, a Random "
        "Forest classifier [10] on eleven hand-crafted image features and a gradient-boosted regressor [11] on nineteen market features, not the "
        "transformer-based models of the base paper. Second, both models are trained on **synthetic data** (section 6.2), because no labelled crop-image "
        "set and no market-price series were available to the project. The method is therefore a working, explainable end-to-end pipeline whose learned "
        "parts have been validated on their own generators and checked once against real photographs (Chapter 8), not a model validated in the field.")
    if not getattr(d, "report", False):
        d.figure(DIAG / "02_high_level_workflow.png", "High-level workflow of CropSight, from upload to delivery", width=6.2)
    d.table([["Step", "Method", "Output"],
             ["1 Capture", "Farmer uploads a JPEG, PNG or WEBP photo (at most 8 MB) with crop, quantity and region", "Draft listing and stored image"],
             ["2 Extract", "OpenCV and scikit-image: foreground mask, HSV colour statistics, GLCM texture, Canny edges, blemishes, relative size", "Vector of 11 features in [0, 1]"],
             ["3 Grade", "Random Forest (250 trees) and SHAP TreeExplainer", "Grade A / B / C / Reject, class probabilities, top-6 feature contributions"],
             ["4 Forecast", "Gradient-boosted point model plus two quantile models on a 19-feature market row; context walked forward 30 days", "Current price, 15-85 % band, 31-day curve, best sell day, SHAP drivers"],
             ["5 Plan delivery", "Weighted score of price, distance, quality fit, reliability and spoilage risk over the buyers", "Top-5 buyers, best route, best sell day"],
             ["6 Trade", "Publish, order and four-state order machine, role-gated at every transition", "Orders: placed, confirmed, in transit, delivered (or cancelled)"],
             ["7 Monitor", "Seeded sensor simulator streamed over WebSocket every 1.4 s; alarm rule on temperature, humidity and shock", "Live traces, cold-chain alert, stored readings"],
             ["8 Review", "Admin KPIs and model cards (accuracy, MAE, R2, importances, training-data disclosure)", "Overview and Model insights screens"]],
            "Pipeline of CropSight", widths=[0.13, 0.5, 0.37], font=9.5)


# ---------------------------------------------------------------------------------------------------------------- 6.2
def sec_dataset(d):
    d.h2("Dataset")
    d.p("No labelled crop-image dataset and no historical market-price feed were available to the project, so the two learned models are trained on "
        "datasets generated by code in the repository. Two public photograph sets were used afterwards, not for training: to test whether the "
        "synthetic-trained grader transfers to real images and to supply real photographs for the demonstration. All four are summarised below.")
    qd, pdset = Q["dataset"], P["dataset"]
    d.table([["Dataset", "Role", "Source and licence", "Size and split"],
             ["Synthetic quality features", "Trains and tests the Random Forest", "`generate_dataset.py`, seed 42; project code",
              f"{qd['rows']:,} rows, {qd['per_grade']:,} per grade, 11 features; {qd['label_noise_fraction'] * 100:.0f} % of labels ({qd['noisy_labels_actual']}) moved to a neighbouring grade; 80/20 stratified split ({qd['train_rows']:,} / {qd['test_rows']:,})"],
             ["Synthetic market series", "Trains and tests the price models", "`generate_dataset.py`, seed 7; project code",
              f"{pdset['rows']:,} rows = 8 crops x 8 regions x every 3rd day, {pdset['date_from']} to {pdset['date_to']}; price {pdset['price_min']:,.0f} to {pdset['price_max']:,.0f} INR per quintal (mean {pdset['price_mean']:,.0f}); 85/15 random split ({P['shipped_gbr']['train_rows']:,} / {P['shipped_gbr']['test_rows']:,})"],
             ["Fresh and Rotten Fruits [8]", "Real-photo check of the grader", "Sultana, Jahan and Uddin, Data in Brief 2022; Hugging Face copy of Project-AgML; CC BY 4.0",
              "3,200 photographs: 8 fruits (apple, banana, grape, guava, jujube, orange, pomegranate, strawberry) x 200 fresh and 200 rotten"],
             ["Vegetable Classification, Bangladesh [9]", "Real tomato, onion and potato photos for the demonstration", "Project-AgML, Hugging Face; CC BY 4.0",
              "First 40 tomato, 40 onion and 40 potato images scanned; four photographs used on the screens"]],
            "Datasets used", widths=[0.19, 0.18, 0.25, 0.38], font=9)
    d.h3("How the synthetic quality set is generated")
    d.p("Each grade is a set of independent normal distributions, one per feature, clipped to [0, 1]. The distributions overlap, so the classifier has "
        "a boundary to learn rather than separate clusters to memorise; then 6 % of the labels are moved to a neighbouring grade (A to B, B to C, C to B, "
        "Reject to C) to imitate grader disagreement. Table 6.2 lists the means used; the standard deviations range from 0.015 to 0.15.")
    d.table([["Feature", "A", "B", "C", "Reject"],
             ["mean_saturation", "0.62", "0.52", "0.40", "0.28"],
             ["color_uniformity", "0.90", "0.74", "0.55", "0.35"],
             ["texture_contrast", "0.18", "0.30", "0.46", "0.64"],
             ["texture_homogeneity", "0.86", "0.72", "0.56", "0.38"],
             ["edge_density", "0.09", "0.15", "0.23", "0.33"],
             ["blemish_ratio", "0.02", "0.07", "0.15", "0.30"],
             ["size_score", "0.82", "0.68", "0.52", "0.35"]],
            "Mean of selected features per grade in the synthetic generator", widths=[0.32, 0.17, 0.17, 0.17, 0.17], font=9.5, align=["l", "c", "c", "c", "c"])
    d.h3("How the synthetic price series is generated")
    d.p("Each row is one crop, region, grade and date. Base prices per quintal are Tomato 1,800, Onion 1,600, Potato 1,200, Wheat 2,400, Rice 2,800, "
        "Mango 4,200, Cotton 6,800 and Maize 2,000; the grade premium is 1.22 (A), 1.05 (B), 0.85 (C) and 0.45 (Reject); the region factor ranges from 0.93 to "
        "1.08. Daily weather, demand, supply and fuel indices are drawn from a generator seeded by a hash of crop, region and date, so the same "
        "inputs always give the same context. The price is the closed formula of section 6.5 times (1 + noise) with noise drawn from N(0, 0.035). "
        "The model therefore learns a known formula; the measured noise floor (MAPE 2.80 %) is the best any model can score on this data.")
    d.h3("Real photographs and how they were used")
    d.p("The 3,200 fruit photographs were passed through the real feature extractor and the shipped grader without any training, and the same "
        "features were then used to train a separate Random Forest on the real fresh/rotten labels, to separate the quality of the extractor from the "
        "quality of the synthetic-trained classifier (section 6.6). Fresh versus rotten is a binary freshness label, not an A/B/C/Reject grade; "
        "mapping fresh to {A, B} and rotten to {C, Reject} is an assumption of this check, and the fruits are not the crops of the application. "
        "The four photographs on the output screens are real tomato, onion and potato images chosen from the first 40 of each crop so that more than one "
        "grade appears; every scanned onion and tomato was graded B, and 39 of 40 potatoes were graded B, which is itself a finding.")


# ---------------------------------------------------------------------------------------------------------------- 6.3
def sec_preprocessing(d):
    d.h2("Preprocessing: Image Features and Market Features")
    d.h3("Computer-vision pipeline")
    d.paras(
        "Every feature of the grader is computed from the pixels of the uploaded photograph; nothing in `feature_extraction.py` is simulated. The steps are:",
    )
    d.numbered([
        "**Decode and normalise.** The image is converted to RGB, shrunk to fit 256 x 256 pixels, centred on a white 256 x 256 canvas and converted to BGR.",
        "**Foreground mask.** The saturation channel is thresholded with Otsu's method [17]; pixels that are bright and nearly unsaturated (value above 235, saturation below 25) are removed as table or paper; a 5 x 5 opening and closing remove specks and holes. If the mask covers less than 3 % or more than 98 % of the canvas the whole image is used instead.",
        "**Colour.** Mean hue (circular mean), mean saturation, mean value, the standard deviation of saturation and a uniformity score derived from it, all inside the mask.",
        "**Texture.** The grey image is quantised to 16 levels and a grey-level co-occurrence matrix is built at distance 2 over four angles [15]; contrast, homogeneity and energy are averaged over the angles.",
        "**Edges.** Canny edges (thresholds 60 and 150) [16]; edge density is the fraction of mask pixels that are edge pixels.",
        "**Blemishes.** The share of mask pixels whose value is more than 1.15 standard deviations darker than the mask mean.",
        "**Size.** The mask area as a share of the canvas, divided by 0.55 and clipped to 1.",
    ])
    d.p("The result is the vector (mean_hue, mean_saturation, mean_value, saturation_std, color_uniformity, texture_contrast, texture_homogeneity, "
        "texture_energy, edge_density, blemish_ratio, size_score), every component in [0, 1]. The extractor uses OpenCV [20] and scikit-image [19]. "
        "Two properties matter for the results: the size score measures how much of the frame the object fills, not its physical size, and the blemish "
        "score depends on the lighting of the photograph, so both are properties of the photograph as much as of the crop.")
    d.h3("Market features")
    d.p("The price model uses nineteen features: sine and cosine of the month, rainfall (mm), average temperature (C), demand index, supply index, "
        "fuel-price index, days to harvest, a year-trend term, the grade premium, a regional factor, and eight one-hot crop columns. For a "
        "request the context (rainfall, temperature, demand, supply and fuel) for a given crop, region and date comes from a generator seeded with "
        "SHA-256 of those three values: the same request on the same day always gives the same numbers, and no external weather or market feed is "
        "involved. This is stated on the admin Model insights screen and repeated here because it determines what the forecast means.")
    d.h3("Cleaning and validation")
    d.p("Uploads are checked for content type (JPEG, PNG or WEBP) and size (8 MB) before decoding. All features are clipped to [0, 1], so a "
        "degenerate photograph (blank, tiny, or a single colour) still yields a valid vector: a 64 x 64 image is graded without error in the tests. "
        "Missing-value handling and outlier removal as in the base paper [1] are not needed because the synthetic generators produce complete rows.")


