def sec_walkthrough(d):
    d.h2("Key Code Walkthroughs")
    d.h3("Foreground mask and texture features")
    d.p("The mask removes the bright, unsaturated table so that colour and texture statistics describe the crop; the co-occurrence matrix is built on the masked grey image.")
    d.code(grab("backend/app/ml/quality/feature_extraction.py", "_, mask = cv2.threshold(sat", 9), "Foreground mask in ml/quality/feature_extraction.py")
    if not getattr(d, "report", False):
        d.code(grab("backend/app/ml/quality/feature_extraction.py", "glcm = graycomatrix(", 12), "Grey-level co-occurrence features in ml/quality/feature_extraction.py")
    d.h3("Grading with an explanation")
    d.p("`grade_image()` extracts the features, takes the class probabilities of the forest and attaches the six largest SHAP contributions for the predicted class.")
    d.code(grab("backend/app/ml/quality/infer.py", "proba = model.predict_proba(vector)[0]", 13), "Grade and probabilities in ml/quality/infer.py")
    d.h3("Price forecast and best sell day")
    d.p("The context is walked forward one day at a time with an exponential blend, the point model is evaluated for each day, and the best day is the maximum over the first fourteen.")
    d.code(grab("backend/app/ml/price/infer.py", "forecast: dict[int, float] = {}", 14), "Forecast loop in ml/price/infer.py")
    if not getattr(d, "report", False):
        d.code(grab("backend/app/ml/price/infer.py", "window = {k: v", 2), "Best sell day in ml/price/infer.py")
    d.h3("Delivery score")
    d.p("Each buyer is scored on five normalised terms; the weights are constants that sum to one, so every ranking can be explained term by term.")
    d.code(grab("backend/app/ml/delivery/recommend.py", "price_norm = min(", 17), "Weighted match score in ml/delivery/recommend.py")
    d.h3("Order state machine")
    d.p("Transitions are declared in one table and checked before any role rule is applied; a distributor who starts transit also creates the shipment whose seed drives the simulator.")
    if not getattr(d, "report", False):
        d.code(grab("backend/app/api/marketplace.py", "VALID_TRANSITIONS = {", 5), "Allowed order transitions in api/marketplace.py")
    d.h3("Sensor simulator step")
    d.p("The simulator moves each quantity by a small random step, injects an event when the countdown reaches zero and decides whether the reading is an anomaly.")
    d.code(grab("backend/app/ml/iot/simulate.py", "def step(self)", 20), "ShipmentSensorState.step() in ml/iot/simulate.py")
    d.h3("Token creation and role guard")
    if not getattr(d, "report", False):
        d.code(grab("backend/app/core/security.py", "def create_access_token", 7), "JWT creation in core/security.py")
    d.code(grab("backend/app/core/security.py", "def require_roles", 7), "Role dependency in core/security.py")


# ---------------------------------------------------------------------------------------------------------------- 6.9
def sec_api(d):
    d.h2("API Design")
    d.p("The API is REST over JSON under `/api` with one WebSocket, 21 endpoints in all. Interactive documentation (Swagger UI) is served by FastAPI at `/docs`. Every endpoint except "
        "health, sign-up, log-in and the option list needs `Authorization: Bearer <token>`; the WebSocket is not authenticated (see section 6.10). Errors have the form `{\"detail\": \"message\"}` with "
        "status 400, 401, 403, 404 or 422.")
    d.table([["Method", "Path", "Role", "Purpose"],
             ["GET", "/api/health", "any", "Liveness"],
             ["POST", "/api/auth/signup", "public", "Create a farmer, buyer or distributor; returns a JWT"],
             ["POST", "/api/auth/login", "public", "Returns a JWT and the user"],
             ["GET", "/api/auth/me", "signed in", "Current user"],
             ["POST", "/api/crops/upload", "farmer", "Multipart photo and crop, region, quantity: draft listing, features, grade, SHAP"],
             ["GET", "/api/crops/mine", "farmer", "Own listings"],
             ["GET", "/api/crops/{id}", "signed in", "One listing"],
             ["POST", "/api/crops/{id}/list", "owner farmer", "Publish with an asking price"],
             ["GET", "/api/prices/options", "public", "Crops, regions, grades"],
             ["POST", "/api/prices/predict", "signed in", "Price, band, 31-day forecast, best day, SHAP"],
             ["GET", "/api/delivery/{id}/recommend", "owner farmer", "Top-5 buyers, route, best day; stored"],
             ["GET", "/api/marketplace/listings", "signed in", "Listed crops, filters crop, region, grade"],
             ["GET", "/api/marketplace/listings/{id}", "signed in", "Listing detail"],
             ["POST", "/api/marketplace/orders", "buyer", "Place an order; listing becomes sold"],
             ["GET", "/api/marketplace/orders/mine", "signed in", "Role-scoped orders"],
             ["PATCH", "/api/marketplace/orders/{id}/status", "farmer, distributor, admin", "Move an order along the state machine"],
             ["GET", "/api/iot/shipments", "signed in", "Shipments in transit"],
             ["GET", "/api/iot/shipments/{id}/history", "signed in", "Latest 60 sensor rows"],
             ["WS", "/api/iot/ws/iot/{id}", "none", "Sensor reading every 1.4 s, stored"],
             ["GET", "/api/admin/overview", "admin", "Users, listings, orders, volume"],
             ["GET", "/api/admin/model-insights", "admin", "Model cards and importances"]],
            "API endpoints", widths=[0.09, 0.36, 0.2, 0.35], font=8.5)
    d.p("**Example: grade a crop.** `POST /api/crops/upload` takes `multipart/form-data` with `crop_type`, `region`, `quantity_kg` and `image`, and returns the listing with its `quality_grade` object "
        "(`grade`, `confidence`, `probabilities`, `features`, `shap_explanation.top_features`). **Example: price.** The request and an abbreviated response:")
    d.code('POST /api/prices/predict\n{"crop_type": "Tomato", "region": "Sunridge Valley", "grade": "B", "listing_id": 7}\n'
           '-> {"current_price": 2272.0, "confidence_low": 2068.0, "confidence_high": 2272.0,\n'
           '    "forecast": {"0": ..., "1": ..., ... "30": ...}, "best_sell_day": 14, "shap_explanation": {"top_features": [...]}}',
           "Price request and response (shape)")
    d.p("When `listing_id` refers to a graded listing, the grade of that listing replaces the grade in the request, so the farmer cannot price a lot at a better grade than it received.")
    d.p("The order status endpoint accepts `{\"status\": \"confirmed\"}`, `\"cancelled\"`, `\"in_transit\"` or `\"delivered\"`; an illegal move returns 400 and an unauthorised actor 403.")


# ---------------------------------------------------------------------------------------------------------------- 6.10
def sec_security(d):
    d.h2("Security and Error Handling")
    d.bullets([
        "**Passwords** are hashed with bcrypt through passlib; sign-up requires a password of at least six characters and a syntactically valid e-mail address (reserved domains such as `.test` are rejected by the validator).",
        "**Tokens.** A signed JWT [23] (HS256, python-jose) with a seven-day expiry carries the user id and role; every protected route decodes it and loads the user, and an invalid or tampered token returns 401.",
        "**Role guards.** `require_roles()` is a dependency that returns 403 for other roles; ownership of a listing is checked in the route (a foreign listing returns 404); the front end repeats the role check with `RequireRole` for navigation only.",
        "**Registration.** Only farmer, buyer and distributor can be created through the API; the admin account exists only in the seed script.",
        "**Uploads.** Only JPEG, PNG and WEBP content types are accepted, with a maximum of 8 MB; files are stored under a random UUID name.",
        "**Order integrity.** The state machine rejects skipped or repeated transitions, a listing can be ordered once, and delivery can only be recorded by the assigned distributor or the admin.",
        "**CORS** allows the origins in `config.py` (port 5173), which is not the port the app is served on (5190); the app works because the browser reaches the API through the Vite proxy on its own origin.",
    ])
    d.p("**Known gaps, found by testing and review, and stated so that they are not mistaken for features.** (1) A default signing secret is committed in `config.py` and must be replaced "
        "for any shared deployment. (2) The sensor WebSocket and the shipment history need no token, and any signed-in user can read any listing or shipment. (3) Any distributor can start transit on any confirmed order. "
        "(4) Order quantity and price are not validated: zero, negative or larger-than-listed values are accepted. (5) Crop and region names are not checked against the catalogue. "
        "(6) A corrupt image sent with an image content type makes the grader raise, the request fails with HTTP 500 and the draft listing created just before is left behind without a grade. "
        "(7) The admin 'gross volume' multiplies a price per quintal by kilograms and so overstates the figure by a factor of 100. (8) There is no rate limiting, HTTPS or audit log. "
        "Gaps 4, 5 and 6 are recorded as expected-failure tests (Chapter 7).")


