    d.table([["Step", "Command", "What it does"],
             ["1", "cd backend; python -m venv venv; venv\\Scripts\\activate; pip install -r requirements.txt", "Creates the environment and installs the pinned backend packages"],
             ["2", "python -m app.ml.quality.train_model; python -m app.ml.price.train_model", "Generates both synthetic datasets if absent and trains both models (written to `app/data/`)"],
             ["3", "python scripts/seed_db.py", "Creates the tables, eight towns, the demo accounts and one sample listing"],
             ["4", "python -m uvicorn app.main:app --port 8000", "Starts the API at http://127.0.0.1:8000 (docs at /docs); do not use `--reload` on Windows"],
             ["5", "cd frontend; npm install; npm run dev", "Starts the web app at http://127.0.0.1:5190, proxying to the API"],
             ["6", "python -m pytest tests -q (in backend)", "Runs the 39 backend tests"]],
            "Installation and execution", widths=[0.07, 0.43, 0.5], font=9)
    if not getattr(d, "report", False):
        d.table([["Role", "E-mail", "Password"],
                 ["Farmer", "farmer@cropsight.dev", "cropsight123"],
                 ["Buyer", "buyer1@cropsight.dev (also buyer2 to buyer4)", "cropsight123"],
                 ["Distributor", "distributor@cropsight.dev", "cropsight123"],
                 ["Admin", "admin@cropsight.dev", "cropsight123"]],
                "Demo accounts created by the seed script", widths=[0.2, 0.55, 0.25], font=10)
    else:
        d.p("The demo accounts created by the seed script are listed in Appendix B.")
    (d.p if not getattr(d, "report", False) else (lambda *a, **k: None))("**Golden path.** Log in as the farmer and grade a crop photograph; forecast its price and plan delivery from the listing workspace, then publish; log in as a buyer and order the lot; "
        "confirm the order as the farmer; start transit as the distributor and open Live monitor; mark the order delivered; open the admin screens for the overview and the model cards.")
